-- One slot. Draft only.
BEGIN;
-- PT103-S2-Q4
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND q.stimulus=$batch01$Politician P: My opponent claims that the government is obligated to raise taxes to increase funding for schools and health care. Because raising taxes to increase funding for schools and health care would make taxpayers upset over their loss of buying power, my opponent is simply mistaken.$batch01$ AND q.prompt=$batch01$Politician P's reasoning is questionable because it involves$batch01$ AND q.correct_choice=$batch01$C$batch01$) THEN RAISE EXCEPTION 'Question changed: PT103-S2-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S2-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$presupposing that a claim is mistaken on the grounds that the person defending it advocates other unpopular views$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q4 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$assuming that a claim is false on the grounds that the person defending it is of questionable character$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q4 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$concluding that a view is false on the grounds that its implementation would lead to unhappiness$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q4 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$appealing to wholly irrelevant issues to deflect attention away from the real issue$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q4 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$insisting that an obligation exists without offering any evidence that it exists$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT103-S2-Q4 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT103-S2-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Opponent's claim$batch01$, $batch01$The government is obligated to raise taxes for schools and health care.$batch01$), (1, $batch01$Politician P's conclusion$batch01$, $batch01$The opponent is mistaken.$batch01$), (2, $batch01$Evidence$batch01$, $batch01$Raising taxes for those purposes would upset taxpayers by reducing buying power.$batch01$), (3, $batch01$Evaluate$batch01$, $batch01$An action can be required and still make people unhappy. Paying a debt may upset the debtor, but that feeling does not erase the debt. To rebut an obligation, P needs a reason it is not owed, not merely a cost of meeting it.$batch01$), (4, $batch01$Goal$batch01$, $batch01$Find the move from an unpleasant consequence of a proposal to the proposal's being false or mistaken.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$P does not cite other unpopular views held by the opponent. P cites a predicted consequence of the specific tax proposal.$batch01$), ($batch01$B$batch01$, $batch01$No claim about the opponent's character appears. This is not Ad Hominem.$batch01$), ($batch01$C$batch01$, $batch01$The view is that the government *must* raise taxes for these services. P calls it mistaken because doing so would reduce taxpayers' buying power and upset them. Unhappiness is compatible with an obligation.$batch01$), ($batch01$D$batch01$, $batch01$Taxpayers' buying power is related to a tax increase, so the issue is not wholly irrelevant. The problem is the inference from that negative consequence to no obligation.$batch01$), ($batch01$E$batch01$, $batch01$P rejects the claim that an obligation exists; P does not insist an obligation exists.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT103-S2-Q4$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
